function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 4;
  gameState = 'PLAYING';

  cameraY = -200;
  nextGenY = 300;
  depthScore = 0;
  invulnTimer = 0;

  player = {
    x: 200, y: 100, w: 16, h: 16,
    vx: 0, vy: 0,
    grounded: false, ammo: 8, maxAmmo: 8, cooldown: 0
  };

  platforms = [];
  enemies = [];
  bullets = [];
  gems = [];

  // Starting floor with gaps on both sides
  platforms.push({ x: 140, y: 250, w: 120, h: 20 });
  generateChunks(1000);
}
